const body = $('Webhook').first().json.body;

return [{
  json: {
    company_id: body.company_id,
    source_type: body.source_type,
    source_content: body.source_content
  }
}];

const raw =
  $json.text ??
  $json.output ??
  $json.response ??
  $json.content ??
  '';

if (!raw || typeof raw !== 'string') {
  throw new Error('LLM returned no text output');
}

let cleaned = raw.trim();

cleaned = cleaned
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

const start = cleaned.indexOf('{');
const end = cleaned.lastIndexOf('}');

if (start === -1 || end === -1 || end <= start) {
  throw new Error('LLM did not return a JSON object');
}

cleaned = cleaned.slice(start, end + 1);

let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error(
    `LLM returned invalid JSON: ${error.message}\n\nRaw output:\n${raw}`
  );
}

return [{
  json: {
    company_id: parsed.company_id || '',
    company_name: parsed.company_name || '',
    industry: parsed.industry || '',
    location: parsed.location || '',
    contact_info: parsed.contact_info || '',
    business_hours: parsed.business_hours || '',
    products: parsed.products || '',
    services: parsed.services || '',
    pricing: parsed.pricing || '',
    customer_segments: parsed.customer_segments || '',
    target_market: parsed.target_market || '',
    sales_channels: parsed.sales_channels || '',
    offers: parsed.offers || '',
    policies: parsed.policies || '',
    workflows: parsed.workflows || '',
    permissions: parsed.permissions || '',
    source_version: 'v1',
    source_expiry: parsed.source_expiry || ''
  }
}];

const extracted = $('Parse Extracted DNA').first().json;
const existing = $('Get Existing Company DNA').first().json;

const changes = [];

const fieldsToCompare = [
  'products',
  'services',
  'pricing',
  'customer_segments',
  'target_market',
  'sales_channels',
  'offers',
  'policies',
  'workflows',
  'permissions'
];

for (const field of fieldsToCompare) {
  const oldValue = String(existing[field] ?? '').trim();
  const newValue = String(extracted[field] ?? '').trim();

  if (newValue && oldValue !== newValue) {
    changes.push({
      field: field,
      old_value: oldValue,
      proposed_value: newValue
    });
  }
}

return [{
  json: {
    company_id: existing.company_id,
    changes: changes,
    changes_count: changes.length
  }
}];

const existing = $('Get Existing Company DNA').first().json;
const changes = $('Compare DNA').first().json.changes || [];

const currentVersion = String(existing.dna_version || 'v0')
  .trim()
  .replace(/^v/i, '');

const currentNumber = parseInt(currentVersion, 10) || 0;

const updated = {
  company_id: existing.company_id,
  company_name: existing.company_name,
  industry: existing.industry,
  location: existing.location,
  contact_info: existing.contact_info,
  business_hours: existing.business_hours,

  products: existing.products || '',
  services: existing.services || '',
  pricing: existing.pricing || '',
  customer_segments: existing.customer_segments || '',
  target_market: existing.target_market || '',
  sales_channels: existing.sales_channels || '',
  offers: existing.offers || '',
  policies: existing.policies || '',
  workflows: existing.workflows || '',
  permissions: existing.permissions || '',

  dna_version: `v${currentNumber + 1}`,

  source_version: existing.source_version || 'v1',
  source_expiry: existing.source_expiry || '',

  lifecycle_state: 'pending_approval',
  approval_status: 'pending',
  approved_by: '',
  approved_at: ''
};

for (const change of changes) {
  if (
    change.proposed_value !== null &&
    change.proposed_value !== undefined &&
    String(change.proposed_value).trim() !== ''
  ) {
    updated[change.field] = change.proposed_value;
  }
}

return [{ json: updated }];

const content = $json.body.source_content;

if (typeof content !== 'string') {
  throw new Error('source_content must be text');
}

if (content.trim().length < 5) {
  throw new Error('source_content is too short');
}

if (content.length > 10000) {
  throw new Error('source_content exceeds 10,000 characters');
}

return items;

const body = $json.body || {};

const content =
  typeof body.source_content === 'string'
    ? body.source_content
    : '';

const promptInjectionPatterns = [
  /ignore\s+(all\s+)?previous\s+instructions/i,
  /ignore\s+(all\s+)?prior\s+instructions/i,
  /ignore\s+the\s+instructions/i,
  /system\s+prompt/i,
  /developer\s+message/i,
  /reveal\s+(your\s+)?(system\s+)?prompt/i,
  /reveal\s+your\s+instructions/i,
  /jailbreak/i,
  /do\s+not\s+follow\s+(the\s+)?previous/i
];

const secretPatterns = [
  /-----BEGIN\s+(RSA\s+|OPENSSH\s+|EC\s+|DSA\s+)?PRIVATE\s+KEY-----/i,
  /\bAKIA[0-9A-Z]{16}\b/i,
  /\bsk-[A-Za-z0-9]{20,}\b/i,
  /\b(password|passwd|pwd)\s*[:=]\s*\S+/i,
  /\b(api[_-]?key|access[_-]?token|secret[_-]?key)\s*[:=]\s*\S+/i,
  /\bAuthorization\s*:\s*Bearer\s+\S+/i,
  /\b(postgresql|postgres|mysql|mongodb|redis):\/\/\S+/i
];

const promptInjectionDetected =
  promptInjectionPatterns.some(pattern => pattern.test(content));

const secretDetected =
  secretPatterns.some(pattern => pattern.test(content));

const blocked =
  promptInjectionDetected || secretDetected;

return [{
  json: {
    ...$json,
    security: {
      status: blocked ? 'blocked' : 'safe',
      prompt_injection_detected: promptInjectionDetected,
      secret_detected: secretDetected,
      blocked_reason:
        promptInjectionDetected
          ? 'prompt_injection'
          : secretDetected
            ? 'secret_detected'
            : ''
    }
  }
}];

const item = $input.first().json;

return [{
  json: {
    company_id: item.company_id,
    evidence: item
  }
}];

const extracted = $('Parse Extracted DNA').first().json;
const existing = $('Get Existing Company DNA').first().json;

const fields = [
  'services',
  'pricing',
  'policies',
  'workflows',
  'permissions'
];

const conflicts = [];

for (const field of fields) {
  const oldValue = String(existing[field] ?? '').trim();
  const newValue = String(extracted[field] ?? '').trim();

  if (!oldValue || !newValue) continue;

  const normalize = value =>
    value
      .toLowerCase()
      .replace(/[.,]/g, '')
      .replace(/\s+/g, ' ')
      .trim();

  const oldNormalized = normalize(oldValue);
  const newNormalized = normalize(newValue);

  if (oldNormalized === newNormalized) continue;

  let isConflict = false;

  if (field === 'pricing') {
    const oldNumbers = oldValue.match(/\d+(?:\.\d+)?/g) || [];
    const newNumbers = newValue.match(/\d+(?:\.\d+)?/g) || [];

    if (
      oldNumbers.length > 0 &&
      newNumbers.length > 0 &&
      oldNumbers[0] !== newNumbers[0]
    ) {
      isConflict = true;
    }
  }

  if (field === 'policies' || field === 'permissions') {
    const oldNegative = /\b(no|not|without|never|prohibited|disabled)\b/i.test(oldValue);
    const newNegative = /\b(no|not|without|never|prohibited|disabled)\b/i.test(newValue);

    if (oldNegative !== newNegative) {
      isConflict = true;
    }
  }

  if (isConflict) {
    conflicts.push({
      field,
      existing_value: oldValue,
      new_value: newValue,
      reason: 'New source contains information that contradicts existing Company DNA'
    });
  }
}

return [{
  json: {
    company_id: existing.company_id,
    conflicts
  }
}];

const data = $('Missing Info Detection').first().json;

const missingFields = data.missing_fields || [];

const questions = {
  products: "What products does your company offer?",
  services: "What services does your company provide?",
  pricing: "What is your pricing or pricing model?",
  customer_segments: "Who are your main customer segments?",
  target_market: "What is your target market?",
  sales_channels: "Which sales channels do you use?",
  offers: "What offers, discounts, or packages do you provide?",
  policies: "What important company policies should be followed?",
  workflows: "What are your standard business workflows?",
  permissions: "What actions require admin approval or special permission?"
};

const targetedQuestions = missingFields.map(field => ({
  field,
  question: questions[field]
})).filter(item => item.question);

return [{
  json: {
    company_id: data.company_id,
    targeted_questions: targetedQuestions
  }
}];

const compare = $('Compare DNA').first().json;
const changes = compare.changes || [];

const impacts = [];

const impactMap = {
  services: [
    'AI agent service knowledge',
    'customer-facing responses',
    'sales workflows'
  ],
  pricing: [
    'pricing responses',
    'sales workflows',
    'customer communications'
  ],
  policies: [
    'policy enforcement',
    'AI agent instructions',
    'approval workflows'
  ],
  workflows: [
    'business process execution',
    'AI agent workflows',
    'automation rules'
  ],
  permissions: [
    'agent permissions',
    'approval requirements',
    'access control rules'
  ]
};

for (const change of changes) {
  const affectedAreas = impactMap[change.field] || [
    'Company DNA dependent workflows'
  ];

  impacts.push({
    field: change.field,
    old_value: change.old_value,
    new_value: change.proposed_value,
    affected_areas: affectedAreas,
    impact_level: change.field === 'permissions' || change.field === 'policies'
      ? 'high'
      : 'medium'
  });
}

return [{
  json: {
    company_id: compare.company_id,
    impacts: impacts,
    impact_count: impacts.length
  }
}];

const input = $input.all();

if (input.length === 0) {
  return [];
}

const results = [];

for (const item of input) {
  const data = item.json;

  const rawQuestions = data.targeted_questions;

  if (!rawQuestions) {
    continue;
  }

  const questions = Array.isArray(rawQuestions)
    ? rawQuestions
    : [rawQuestions];

  for (let i = 0; i < questions.length; i++) {
    const q = questions[i];

    if (!q || !q.field || !q.question) {
      continue;
    }

    results.push({
      json: {
        question_id: `Q-${data.company_id}-${q.field}-${$execution.id}-${i + 1}`,
        company_id: data.company_id,
        dna_version: 'v6',
        missing_field: q.field,
        question: q.question,
        status: 'pending',
        answer: '',
        answered_at: '',
        created_at: new Date().toISOString()
      }
    });
  }
}

return results;

const generated = $('Test Scenario').first().json;

const scenarios = Array.isArray(generated.test_scenarios)
  ? generated.test_scenarios
  : [];

if (scenarios.length === 0) {
  return [];
}

const dnaVersion = $('Get Existing Company DNA').first().json.dna_version;

return scenarios.map((scenario, index) => ({
  json: {
    scenario_id: `SC-${generated.company_id}-${$execution.id}-${index + 1}`,
    company_id: generated.company_id,
    dna_version: String(dnaVersion || '').trim(),
    scenario: (scenario.test || '').trim(),
    expected_behavior: (scenario.expected_result || '').trim(),
    actual_result: '',
    status: 'pending',
    created_at: new Date().toISOString(),
    tested_at: ''
  }
}));

const impactData = $('Impact Analysis').first().json;

const impacts = Array.isArray(impactData.impacts)
  ? impactData.impacts
  : [];

const testScenarios = [];

for (const impact of impacts) {
  const field = impact.field;
  const newValue = impact.new_value ?? '';

  if (!field) {
    continue;
  }

  testScenarios.push({
    field: field,
    test: `Verify the updated ${field} information is correctly applied.`,
    expected_result: `Agent uses "${newValue}".`
  });
}

return [{
  json: {
    company_id: impactData.company_id,
    test_scenarios: testScenarios,
    scenario_count: testScenarios.length
  }
}];

const data = $('Missing Info Detection').first().json;

const fields = Array.isArray(data.missing_fields)
  ? data.missing_fields
  : [];

if (fields.length === 0) {
  return [];
}

return fields.map((field, index) => ({
  json: {
    finding_id: `F-${data.company_id}-missing-${$execution.id}-${index + 1}`,
    company_id: data.company_id,
    dna_version: 'v3',
    finding_type: 'missing_info',
    field: field,
    details: `Required DNA field "${field}" is missing.`,
    old_value: '',
    new_value: '',
    severity: 'medium',
    status: 'open',
    source_evidence_id: '',
    created_at: new Date().toISOString(),
    resolved_at: ''
  }
}));

const extracted = $('Parse Extracted DNA').first().json;

const requiredFields = [
  'products',
  'services',
  'pricing',
  'customer_segments',
  'target_market',
  'sales_channels',
  'offers',
  'policies',
  'workflows',
  'permissions'
];

const missingFields = requiredFields.filter(field => {
  const value = extracted[field];
  return value === null || value === undefined || String(value).trim() === '';
});

return [{
  json: {
    company_id: extracted.company_id,
    missing_fields: missingFields,
    missing_count: missingFields.length
  }
}];

const existing = $('Get Existing Company DNA').first().json;

const currentVersion = String(existing.dna_version || 'v0')
  .trim()
  .replace(/^v/i, '');

const nextVersion = `v${(parseInt(currentVersion, 10) || 0) + 1}`;

return [{
  json: {
    company_id: existing.company_id,
    dna_version: nextVersion
  }
}];

const body = $json.body || {};

const expiryRaw = body.source_expiry;

let expired = false;
let expiryDate = null;

if (expiryRaw && String(expiryRaw).trim() !== '') {
  expiryDate = new Date(String(expiryRaw).trim());

  if (!isNaN(expiryDate.getTime())) {
    expired = expiryDate.getTime() < Date.now();
  }
}

return [{
  json: {
    ...$json,
    source_expiry: expiryRaw || '',
    source_expired: expired,
    source_expiry_valid:
      !expiryRaw || !isNaN(expiryDate?.getTime())
  }
}];

return [{
  json: {
    ...$json,
    lifecycle_state: 'rejected',
    approval_status: 'rejected'
  }
}];

