const items = $input.all();

let missingFieldsList = [];
let questionsList = [];
let testScenariosList = [];

for (const item of items) {
  const data = item.json;

  if (data.field || data.details || data.finding_type === 'missing_info') {
    missingFieldsList.push({
      field: data.field || data.missing_field || 'unknown_field',
      details: data.details || `Required DNA field is missing.`
    });
  }

  if (data.question) {
    questionsList.push(data.question);
  } else if (data.target_question) {
    questionsList.push(data.target_question);
  }

  if (data.scenario || data.test_scenario || data.description) {
    testScenariosList.push(data.scenario || data.test_scenario || data.description);
  }
}

return [{
  json: {
    status: "success",
    assistant_message: "DNA baseline analysis completed.",
    missing_fields: missingFieldsList,
    questions: questionsList,
    test_scenarios: testScenariosList,
    requires_user_input: true
  }
}];
